class Response{constructor(e,s=200,t={}){this.cookies=[],this.original=e instanceof Response?e.getOriginal():e,this.status=s,this._headers=t}getCookies(){return this.cookies}setCookie(e){this.cookies.push(e)}getOriginal(){return this.original}getStatus(){return this.status}get headers(){return this._headers.getCookies||Object.defineProperty(this._headers,"getCookies",{value:this.getCookies.bind(this)}),this._headers.setCookie||Object.defineProperty(this._headers,"setCookie",{value:this.setCookie.bind(this)}),this._headers}setCookiesToHeaders(){this._headers={...this._headers,"set-cookie":this.cookies.map((e=>e.toString()))}}setOriginal(e){return this.original=e,this}setServerResponse(e){return this.res=e,this.res.statusCode=this.status,this._headers={...this._headers,...this.res.getHeaders()},this}mergeResponse(e){this.status=e.status,this._headers={...this._headers,...e.headers},this.original=e.getOriginal(),this.cookies=[...this.cookies,...e.headers.getCookies()]}getServerResponse(){return this.res}setHeader(e,s){return this.res&&this.res.setHeader(e,s),this._headers={...this.headers,[e]:s},this}}export{Response as R};
